module stan_eater (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] course_0, course_1, course_2, course_3,\n                 course_4, course_5, course_6, course_7,\n    input [7:0] m,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State machine declarations\n    localparam [3:0] IDLE       = 4'd0;\n    localparam [3:0] INIT_DP    = 4'd1;\n    localparam [3:0] INIT_COPY  = 4'd2;\n    localparam [3:0] COMPUTE_R  = 4'd3;\n    localparam [3:0] COMPUTE_S  = 4'd4;\n    localparam [3:0] NEXT_S     = 4'd5;\n    localparam [3:0] NEXT_R     = 4'd6;\n    localparam [3:0] NEXT_I_1   = 4'd7;\n    localparam [3:0] COPY       = 4'd8;\n    localparam [3:0] NEXT_I_2   = 4'd9;\n    localparam [3:0] DONE_STATE = 4'd10;\n\n    reg [3:0] state;\n    reg [3:0] i;\n    reg [7:0] r;\n    reg [1:0] s;\n    reg [8:0] copy_index;\n\n    // DP arrays\n    reg [15:0] dp_current [0:128][0:2];\n    reg [15:0] dp_next [0:128][0:2];\n\n    // Course storage\n    reg [7:0] course_reg [0:7];\n\n    // Computation registers\n    reg [7:0] current_rate;\n    reg [15:0] calories;\n    reg [7:0] next_r;\n    reg [1:0] next_s;\n    reg [15:0] value1, value2, max_value;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            i <= 4'd0;\n            r <= 8'd0;\n            s <= 2'd0;\n            copy_index <= 9'd0;\n            for (integer j = 0; j < 8; j = j + 1) course_reg[j] <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        course_reg[0] <= course_0;\n                        course_reg[1] <= course_1;\n                        course_reg[2] <= course_2;\n                        course_reg[3] <= course_3;\n                        course_reg[4] <= course_4;\n                        course_reg[5] <= course_5;\n                        course_reg[6] <= course_6;\n                        course_reg[7] <= course_7;\n                        state <= INIT_DP;\n                    end\n                end\n\n                INIT_DP: begin\n                    i <= 4'd7;\n                    state <= INIT_COPY;\n                    copy_index <= 9'd0;\n                end\n\n                INIT_COPY: begin\n                    dp_next[copy_index / 3][copy_index % 3] <= 16'd0;\n                    if (copy_index < 9'd386) begin\n                        copy_index <= copy_index + 9'd1;\n                    end else begin\n                        state <= COMPUTE_R;\n                        r <= 8'd0;\n                    end\n                end\n\n                COMPUTE_R: begin\n                    if (r > 8'd128) begin\n                        state <= NEXT_I_1;\n                    end else begin\n                        s <= 2'd0;\n                        state <= COMPUTE_S;\n                    end\n                end\n\n                COMPUTE_S: begin\n                    if (s > 2'd2) begin\n                        state <= NEXT_R;\n                    end else if (s == 2'd2 && r != m) begin\n                        dp_current[r][s] <= 16'd0;\n                        state <= NEXT_S;\n                    end else begin\n                        current_rate = (s == 2'd2) ? m : r;\n\n                        if (current_rate < course_reg[i])\n                            calories = current_rate;\n                        else\n                            calories = course_reg[i];\n\n                        next_r = (current_rate * 8'd2) / 8'd3;\n                        next_s = 2'd0;\n                        value1 = calories + dp_next[next_r][next_s];\n\n                        if (s < 2'd2) begin\n                            next_s = s + 2'd1;\n                            next_r = current_rate;\n                        end else begin\n                            next_s = 2'd2;\n                            next_r = m;\n                        end\n                        value2 = dp_next[next_r][next_s];\n\n                        max_value = (value1 > value2) ? value1 : value2;\n                        dp_current[r][s] <= max_value;\n\n                        state <= NEXT_S;\n                    end\n                end\n\n                NEXT_S: begin\n                    s <= s + 2'd1;\n                    state <= COMPUTE_S;\n                end\n\n                NEXT_R: begin\n                    r <= r + 8'd1;\n                    state <= COMPUTE_R;\n                end\n\n                NEXT_I_1: begin\n                    copy_index <= 9'd0;\n                    state <= COPY;\n                end\n\n                COPY: begin\n                    dp_next[copy_index / 3][copy_index % 3] <= dp_current[copy_index / 3][copy_index % 3];\n                    if (copy_index < 9'd386) begin\n                        copy_index <= copy_index + 9'd1;\n                    end else begin\n                        if (i == 4'd0) \n                            state <= DONE_STATE;\n                        else begin\n                            state <= NEXT_I_2;\n                        end\n                    end\n                end\n\n                NEXT_I_2: begin\n                    i <= i - 4'd1;\n                    r <= 8'd0;\n                    state <= COMPUTE_R;\n                end\n\n                DONE_STATE: begin\n                    result <= dp_next[m][0];\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule